CREATE TABLE IF NOT EXISTS cost_centers (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id SERIAL PRIMARY KEY, name VARCHAR(180) NOT NULL, document VARCHAR(20) UNIQUE, phone VARCHAR(30), email VARCHAR(160), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS financial_accounts (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, account_type VARCHAR(30) NOT NULL, initial_balance DOUBLE PRECISION NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receivables (id SERIAL PRIMARY KEY, sale_id INTEGER NOT NULL UNIQUE REFERENCES sales(id), customer_id INTEGER NOT NULL REFERENCES customers(id), seller_id INTEGER NOT NULL REFERENCES sellers(id), due_date DATE NOT NULL, original_amount DOUBLE PRECISION NOT NULL, interest_amount DOUBLE PRECISION NOT NULL DEFAULT 0, fine_amount DOUBLE PRECISION NOT NULL DEFAULT 0, discount_amount DOUBLE PRECISION NOT NULL DEFAULT 0, paid_amount DOUBLE PRECISION NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'aberto', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receivable_payments (id SERIAL PRIMARY KEY, receivable_id INTEGER NOT NULL REFERENCES receivables(id), account_id INTEGER NOT NULL REFERENCES financial_accounts(id), amount DOUBLE PRECISION NOT NULL, payment_method VARCHAR(30) NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, note TEXT, reversed BOOLEAN NOT NULL DEFAULT FALSE, responsible_id INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payables (id SERIAL PRIMARY KEY, supplier_id INTEGER REFERENCES suppliers(id), cost_center_id INTEGER NOT NULL REFERENCES cost_centers(id), category VARCHAR(80) NOT NULL, description VARCHAR(200) NOT NULL, competence_date DATE NOT NULL, due_date DATE NOT NULL, original_amount DOUBLE PRECISION NOT NULL, paid_amount DOUBLE PRECISION NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'aberto', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payable_payments (id SERIAL PRIMARY KEY, payable_id INTEGER NOT NULL REFERENCES payables(id), account_id INTEGER NOT NULL REFERENCES financial_accounts(id), amount DOUBLE PRECISION NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, note TEXT, reversed BOOLEAN NOT NULL DEFAULT FALSE, responsible_id INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cash_transactions (id SERIAL PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES financial_accounts(id), direction VARCHAR(10) NOT NULL, amount DOUBLE PRECISION NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, source_type VARCHAR(40) NOT NULL, source_id INTEGER, description VARCHAR(240) NOT NULL, reversed BOOLEAN NOT NULL DEFAULT FALSE, responsible_id INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
